export function modelMetrics(data,anchors,params,mode){const points={};for(const[k,v]of Object.entries(anchors[mode])){const p=deformPoint(v,data,params);points[k]={x:p[mode.endsWith('Side')?2:0]*1000,y:-p[1]*1000};}return imageMetrics(points,mode);}
